#!/usr/bin/env bash
# Generated by scripts/07_sync.py — review before running.
# Makes the bucket publicly readable and CORS-enabled for the viewer origin.
# Run once, before or after the first sync.
set -euo pipefail

BUCKET="freburg-immune-data-viewer-544227292049-us-east-1-an"
REGION="us-east-1"
HERE="$(cd "$(dirname "$0")" && pwd)"

# Public-read requires the account-level block to allow bucket policies.
aws s3api put-public-access-block \
  --bucket "$BUCKET" --region "$REGION" \
  --public-access-block-configuration \
  "BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=false,RestrictPublicBuckets=false"

aws s3api put-bucket-policy \
  --bucket "$BUCKET" --region "$REGION" \
  --policy "file://$HERE/bucket-policy.json"

aws s3api put-bucket-cors \
  --bucket "$BUCKET" --region "$REGION" \
  --cors-configuration "file://$HERE/cors.json"

echo "Applied bucket policy and CORS to $BUCKET"
